import { useQuery } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import type { Claim } from '../claims/claims';
import { gradeOn, usePeople } from '../people/people';
import { useCurrentSheet, useSheetToday } from '../session/session';

// A rate is a percent with two decimals ("12.50") for a grade from a from-date on (null: from the
// beginning of time); a grade may have several. A date uses the rate whose from-date is the latest on
// or before it; a date before every rate of its grade, or a grade with no rate, has none (n/a).
// Due is worked out in whole cents and hundredths of a percent with BigInt, so no floating-point
// error shows: amount × rate / 100, rounded half to even to two decimals.
export type Rate = { grade: string; rate: string; from: string | null };
export type RateInput = { grade: string; rate: string; from: string };

/** 0.00 or more, with up to two decimals. */
export const PERCENT = /^\d{1,5}(\.\d{1,2})?$/;

/** What a due shows when its grade has no rate. */
export const NA = 'n/a';

const base = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/rates`;
export const ratesKey = (sheet: string) => ['sheet', sheet, 'rates'] as const;

/** The active sheet's rates, by grade. */
export function useRates() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: ratesKey(sheet ?? ''),
    queryFn: () => getJson<{ rates: Rate[] }>(base(sheet!)).then((r) => r.rates),
    enabled: !!sheet,
  });
}

export const setRate = (sheet: string, user: string, input: RateInput) => postJson<Rate>(base(sheet), input, user);

/** A two-decimal string (may be negative) as a whole number of hundredths. */
export const hundredths = (value: string): bigint => {
  const negative = value.startsWith('-');
  const [whole, frac = ''] = (negative ? value.slice(1) : value).split('.');
  const n = BigInt(whole) * 100n + BigInt((frac + '00').slice(0, 2));
  return negative ? -n : n;
};

/** Hundredths shown with two decimals. */
export const show = (n: bigint): string => {
  const sign = n < 0n ? '-' : '';
  const abs = n < 0n ? -n : n;
  return `${sign}${abs / 100n}.${String(abs % 100n).padStart(2, '0')}`;
};

/** The due on an amount at a rate, in cents: amount × rate / 100, rounded half to even. */
export function dueCents(amount: string, rate: string): bigint {
  return percentOf(hundredths(amount), hundredths(rate));
}

/** A percent (hundredths of a percent) of cents, in cents, rounded half to even. */
export function percentOf(cents: bigint, percent: bigint): bigint {
  const product = cents * percent; // cents × hundredths of a percent
  const sign = product < 0n ? -1n : 1n;
  const abs = sign * product;
  const whole = abs / 10000n;
  const rest = abs % 10000n;
  const up = rest > 5000n || (rest === 5000n && whole % 2n === 1n);
  return sign * (up ? whole + 1n : whole);
}

/** A claim's due in cents: a settled claim's is the one fixed when it was settled; an open or draft
 *  claim's is live, at its grade's rate in force on the claim's date, and at least the sheet's floor
 *  (cents), plus the late charge: the late percent (hundredths of a percent) of that floored due for each
 *  full 30 days it is overdue (`lateSpans`), rounded like due. A correction (a negative amount) has neither
 *  the floor nor the late charge. Undefined for n/a. */
export function claimDueCents(claim: Claim, rate: string | undefined, floor: bigint, latePct = 0n, lateSpans = 0n): bigint | undefined {
  if (claim.status === 'SETTLED') return claim.settledDue === null ? undefined : hundredths(claim.settledDue);
  if (rate === undefined) return undefined;
  const due = dueCents(claim.amount, rate);
  if (due < 0n || claim.amount.startsWith('-')) return due; // a correction: no floor, no late charge
  const floored = due < floor ? floor : due;
  return floored + percentOf(floored, latePct * lateSpans);
}

/** The grade's rate (two decimals) in force on a date (yyyy-mm-dd), or undefined when none applies. */
export function rateOn(rates: Rate[], grade: string | undefined, date: string | undefined): string | undefined {
  if (date === undefined) return undefined;
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  return found?.rate;
}

/** The rate (two decimals) for a grade in force on a date (default: the sheet's today), or undefined. */
export function useGradeRate() {
  const rates = useRates().data ?? [];
  const today = useSheetToday();
  return (grade: string | undefined, date: string | undefined = today) => rateOn(rates, grade, date);
}

/** The rate in force on a date (default: the sheet's today) for the person's grade in force on that date,
 *  looked up by person id. */
export function usePersonRate() {
  const people = usePeople().data ?? [];
  const rateOf = useGradeRate();
  const today = useSheetToday();
  return (personId: number, date: string | undefined = today) =>
    rateOf(gradeOn(people.find((p) => p.id === personId), date), date);
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HomeMain } from '../../slots/defs/homeMain';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { useClaimDue, useClaims, useCounts } from '../claims/claims';
import { GRADES, gradeOn, usePeople } from '../people/people';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import { NA, PERCENT, ratesKey, setRate, show, useGradeRate, usePersonRate, useRates } from './rates';
import type { RateInput } from './rates';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

const EMPTY: RateInput = { grade: 'A', rate: '', from: '' };

// The sheet's rates: a form that sets a grade's rate from a from-date (none: from the beginning of
// time), replacing any rate it had for that from-date; each grade's rate in force on the sheet's today
// (n/a when none applies); and every rate set, by grade then from-date.
function Rates() {
  const [sheet] = useCurrentSheet();
  const [user] = useCurrentUser();
  const rateOf = useGradeRate();
  const rates = useRates().data ?? [];
  const [form, setForm] = useState<RateInput>(EMPTY);
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const save = useMutation({
    mutationFn: (input: RateInput) => setRate(sheet!, user, input),
    onSuccess: async () => {
      setForm((f) => ({ ...f, rate: '', from: '' }));
      await queryClient.invalidateQueries({ queryKey: ratesKey(sheet!) });
    },
    onError: () =>
      setError('The rate could not be set: it must be a percent of 0.00 or more, with up to two decimals, and a date if from is given.'),
  });

  if (!sheet) return null;

  const change = (patch: Partial<RateInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (!PERCENT.test(form.rate.trim())) {
      setError('The rate must be a percent of 0.00 or more, with up to two decimals.');
      return;
    }
    const from = form.from.trim();
    if (from !== '' && !DATE.test(from)) {
      setError('The from-date must be a date (yyyy-mm-dd).');
      return;
    }
    once(() => save.mutateAsync({ grade: form.grade, rate: form.rate.trim(), from }));
  };

  return (
    <section data-testid="rates">
      <h2>Rates</h2>
      <form data-testid="rate-form" onSubmit={submit}>
        <select data-testid="rate-form-grade" value={form.grade} onChange={(e) => change({ grade: e.target.value })}>
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
        <input
          data-testid="rate-form-pct"
          placeholder="Percent"
          inputMode="decimal"
          value={form.rate}
          onChange={(e) => change({ rate: e.target.value })}
        />
        <input
          data-testid="rate-form-from"
          type="date"
          placeholder="From (yyyy-mm-dd)"
          value={form.from}
          onChange={(e) => change({ from: e.target.value })}
        />
        <button type="submit" data-testid="rate-form-submit" disabled={save.isPending}>
          Set rate
        </button>
        {error && <span data-testid="rate-form-error">{error}</span>}
      </form>
      <table data-testid="rate-list">
        <thead>
          <tr>
            <th>Grade</th>
            <th>Rate today (%)</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => (
            <tr key={g}>
              <td>{g}</td>
              <td data-testid={`rate-current-${g}`}>{rateOf(g) ?? NA}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table data-testid="rate-history">
        <thead>
          <tr>
            <th>Grade</th>
            <th>From</th>
            <th>Rate (%)</th>
          </tr>
        </thead>
        <tbody>
          {rates.map((r) => (
            <tr key={`${r.grade}-${r.from ?? 'start'}`} data-testid={`rate-row-${r.grade}-${r.from ?? 'start'}`}>
              <td>{r.grade}</td>
              <td data-testid="rate-from">{r.from ?? 'start'}</td>
              <td data-testid="rate-pct">{r.rate}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

function DueColumn() {
  return <th>Due</th>;
}

/** A person's due-total in cents: the already-rounded figures of their claims that count added up
 *  (0 when none counts). Undefined for n/a: their grade has no rate today and no claim keeps a figure
 *  (a settled claim's fixed due, or one dated under another grade than today's that has a due). */
export function useDueTotal() {
  const claims = useClaims().data ?? [];
  const rateOf = usePersonRate();
  const counts = useCounts();
  const claimDue = useClaimDue();
  const people = usePeople().data ?? [];
  const today = useSheetToday();
  return (personId: number) => {
    const person = people.find((p) => p.id === personId);
    const gradeToday = gradeOn(person, today);
    const figures = claims
      .filter((c) => c.personId === personId && counts(c))
      .map((c) => ({ claim: c, due: claimDue(c, rateOf(personId, c.date)) }));
    const kept = figures.some((f) => f.due !== undefined
      && (f.claim.status === 'SETTLED' || gradeOn(person, f.claim.date) !== gradeToday));
    if (rateOf(personId) === undefined && !kept) return undefined;
    return figures.reduce((n, f) => n + (f.due ?? 0n), 0n);
  };
}

// A person's due-total: n/a when their grade has no rate today, unless a claim keeps a figure.
function PersonDueTotal({ personId }: { personId: number }) {
