            inputMode="decimal"
            value={floor}
            onChange={(e) => {
              setFloor(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <span>
          now <strong data-testid="setting-floor-current">{settings?.floor ?? ''}</strong>
        </span>{' '}
        <label>
