          <input
            data-testid="setting-terms"
            placeholder="Unchanged"
            inputMode="numeric"
            value={terms}
            onChange={(e) => {
              setTerms(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <span>
          now <strong data-testid="setting-terms-current">{settings?.terms ?? ''}</strong>
        </span>{' '}
        <label>
